def choose_move(observation):
    # Defensive defaults
    # Try to read up to possible fields safely
    targets = []
    # Common possible keys
    # Resource collection may provide 'resources', 'target', 'closest_resource'
    if isinstance(observation, dict):
        if 'target' in observation:
            targets.append(observation.get('target'))
        if 'closest_resource' in observation:
            targets.append(observation.get('closest_resource'))
        if 'resources' in observation and isinstance(observation.get('resources'), (list, tuple)):
            for r in observation.get('resources', []):
                targets.append(r)
        if 'enemy' in observation:
            targets.append(observation.get('enemy'))
        if 'goal' in observation:
            targets.append(observation.get('goal'))
        if 'position' in observation:
            me = observation.get('position')
        else:
            me = observation.get('self', observation.get('my_position', (0, 0)))
        if isinstance(me, dict):
            me = me.get('x', 0), me.get('y', 0)
        if not isinstance(me, tuple):
            me = (0, 0)
        x, y = me
    else:
        # Fallback defaults
        x, y = 0, 0
        targets = []

    # Heuristic helper: clamp to -1..1
    def clamp(n):
        return -1 if n < -1 else (1 if n > 1 else n)

    # Simple reactive policy:
    # 1) If any target exists and is close, move towards it (dx,dy in -1..1)
    # 2) Else stay or patrol around: prefer left, then up, then right, then down
    best_dx, best_dy = 0, 0
    best_score = -10

    # Consider a few directions
    directions = [(-1,-1), (-1,0), (-1,1), (0,-1), (0,0), (0,1), (1,-1), (1,0), (1,1)]
    # Normalize to ensure within bounds
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        # Score: prefer moving toward any target if available
        score = 0
        for t in targets:
            try:
                tx, ty = t.get('x', t[0]), t.get('y', t[1])
            except Exception:
                continue
            dist_before = max(abs(tx - x), abs(ty - y))
            dist_after  = max(abs(tx - nx), abs(ty - ny))
            if dist_after < dist_before:
                score += 1
        # If no targets, promote a small random-like patrol preference
        if not targets and (dx != 0 or dy != 0):
            score -= 0.5  # discourage unnecessary moves when nothing to do

        # Keep staying within bounds modestly
        if -1 <= dx <= 1 and -1 <= dy <= 1:
            if score > best_score:
                best_score = score
                best_dx, best_dy = dx, dy

    # Defensive fallback if somehow no direction chosen
    best_dx = clamp(best_dx)
    best_dy = clamp(best_dy)
    return [best_dx, best_dy]

